<?php
require_once __DIR__ . '/_layout.php';requirePermission('expenses.manage');
if(requestMethod()==='POST'){requireCsrfPost();$action=$_POST['action']??'';try{if($action==='create'){$agencyId=(int)$_POST['agency_id'];requireAgencyAccess($agencyId);$amount=positiveMoney($_POST['amount']??'');if($amount===null)throw new InvalidArgumentException('Enter a valid expense amount.');$receipt=null;if(isset($_FILES['receipt'])&&($_FILES['receipt']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE)$receipt=storeValidatedDocument($_FILES['receipt'],'expense_receipts')['path'];dbExecute('INSERT INTO expenses(agency_id,vehicle_id,contract_id,category,supplier,description,amount,currency,expense_date,status,receipt_path,created_by)VALUES(:agency,:vehicle,:contract,:category,:supplier,:description,:amount,:currency,:date,\'pending\',:receipt,:user)',['agency'=>$agencyId,'vehicle'=>($_POST['vehicle_id']??'')?:null,'contract'=>($_POST['contract_id']??'')?:null,'category'=>validateChoice($_POST['category']??'',['maintenance','repair','insurance','technical_inspection','tax','cleaning','fuel','leasing','parking','fine','partner_commission','administration','other'],'other'),'supplier'=>trim((string)($_POST['supplier']??'')),'description'=>trim((string)($_POST['description']??'')),'amount'=>$amount,'currency'=>appConfig('currency'),'date'=>$_POST['expense_date'],'receipt'=>$receipt,'user'=>currentUserId()]);$id=(int)db()->lastInsertId();auditLog('expense.created','expense',$id,null,['amount'=>$amount],$agencyId);flash('success','Expense created for approval.');}elseif($action==='approve'){$expense=dbFetchOne('SELECT * FROM expenses WHERE id=:id',['id'=>(int)$_POST['id']]);if(!$expense)throw new InvalidArgumentException('Expense not found.');requireAgencyAccess($expense['agency_id']);dbExecute("UPDATE expenses SET status='approved',approved_at=NOW(),approved_by=:user WHERE id=:id",['user'=>currentUserId(),'id'=>$expense['id']]);auditLog('expense.approved','expense',$expense['id'],['status'=>$expense['status']],['status'=>'approved'],$expense['agency_id']);flash('success','Expense approved.');}}catch(InvalidArgumentException|DomainException $exception){flash('danger',$exception->getMessage());}catch(Throwable $exception){reportDatabaseError($exception,'Expense operation failed');flash('danger','The expense operation could not be completed.');}safeRedirect('expenses.php');}
$ids=currentAgencyIds();if(!$ids)$ids=[0];$ph=implode(',',array_fill(0,count($ids),'?'));$agencies=dbFetchAll("SELECT id,name FROM agencies WHERE id IN ($ph) ORDER BY name",$ids);$vehicles=dbFetchAll("SELECT id,registration_number FROM vehicles WHERE agency_id IN ($ph) AND archived_at IS NULL ORDER BY registration_number",$ids);$expenses=dbFetchAll("SELECT e.*,a.name agency_name,v.registration_number FROM expenses e JOIN agencies a ON a.id=e.agency_id LEFT JOIN vehicles v ON v.id=e.vehicle_id WHERE e.agency_id IN ($ph) AND e.archived_at IS NULL ORDER BY e.expense_date DESC LIMIT 100",$ids);$profitability=dbFetchAll("SELECT v.registration_number,v.brand,v.model,COALESCE(rev.revenue,0) revenue,COALESCE(exp.expenses,0) expenses,COALESCE(rev.revenue,0)-COALESCE(exp.expenses,0) estimated_profit FROM vehicles v LEFT JOIN(SELECT r.vehicle_id,SUM(p.amount) revenue FROM payments p JOIN reservations r ON r.id=p.reservation_id WHERE p.status='paid' GROUP BY r.vehicle_id)rev ON rev.vehicle_id=v.id LEFT JOIN(SELECT vehicle_id,SUM(amount) expenses FROM expenses WHERE status='approved' AND archived_at IS NULL GROUP BY vehicle_id)exp ON exp.vehicle_id=v.id WHERE v.agency_id IN ($ph) AND v.archived_at IS NULL ORDER BY estimated_profit DESC",$ids);
backofficeHeader(t('expenses'),'expenses.php');?><?php pageHeader('Expenses and profitability', 'Record and approve operating costs with fleet profitability context.', ['breadcrumbs'=>[['label'=>'Finance'],['label'=>'expenses']],'primary'=>['label'=>'Add expense','href'=>'#new-expense']]); ?><div class="grid"><section class="card" id="new-expense"><h2>Record expense</h2><form method="post" enctype="multipart/form-data"><?=csrfField()?><input type="hidden" name="action" value="create"><label>Agency<select name="agency_id"><?php foreach($agencies as $a):?><option value="<?=e($a['id'])?>"><?=e($a['name'])?></option><?php endforeach;?></select></label><label>Vehicle (optional)<select name="vehicle_id"><option value="">Agency expense</option><?php foreach($vehicles as $v):?><option value="<?=e($v['id'])?>"><?=e($v['registration_number'])?></option><?php endforeach;?></select></label><label>Category<select name="category"><?php foreach(['maintenance','repair','insurance','technical_inspection','tax','cleaning','fuel','leasing','parking','fine','partner_commission','administration','other'] as $c):?><option><?=e($c)?></option><?php endforeach;?></select></label><label>Supplier<input name="supplier"></label><label>Description<input name="description" required></label><label>Amount<input name="amount" required inputmode="decimal"></label><label>Date<input type="date" name="expense_date" value="<?=e(date('Y-m-d'))?>" required></label><label>Receipt<input type="file" name="receipt" accept="application/pdf,image/jpeg,image/png,image/webp"></label><button class="btn primary">Record expense</button></form></section><section class="card"><h2>Expense register</h2><div class="table-wrap"><table><tr><th>Date</th><th>Agency</th><th>Vehicle</th><th>Category</th><th>Amount</th><th>Status</th></tr><?php foreach($expenses as $e):?><tr><td><?=e($e['expense_date'])?></td><td><?=e($e['agency_name'])?></td><td><?=e($e['registration_number'])?></td><td><?=e($e['category'])?></td><td><?=money($e['amount'],$e['currency'])?></td><td><?=statusBadge($e['status'])?><?php if($e['status']==='pending'):?><form method="post"><?=csrfField()?><input type="hidden" name="action" value="approve"><input type="hidden" name="id" value="<?=e($e['id'])?>"><button class="btn secondary">Approve</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></section></div><section class="card" style="margin-top:1rem"><h2>Estimated vehicle profitability</h2><p><small>Revenue from recorded paid payments minus approved vehicle expenses. This is an estimate when accounting data are incomplete.</small></p><div class="table-wrap"><table><tr><th>Vehicle</th><th>Revenue</th><th>Expenses</th><th>Estimated profitability</th></tr><?php foreach($profitability as $p):?><tr><td><?=e($p['registration_number'].' '.$p['brand'].' '.$p['model'])?></td><td><?=money($p['revenue'])?></td><td><?=money($p['expenses'])?></td><td><?=money($p['estimated_profit'])?></td></tr><?php endforeach;?></table></div></section><?php backofficeFooter();
